using Google.Protobuf;
using Microsoft.AspNetCore.Http;
using Treehammock.SessionValidation.Client;
using Treehammock.SessionValidation.Contracts;
using Treehammock.SessionValidation.Contracts.V1;
using Xunit;
namespace Treehammock.SessionValidation.ClientTests;
public sealed class ReplyTests
{
    [Theory][InlineData("active",200)][InlineData("unauthenticated",401)][InlineData("forbidden",403)][InlineData("unavailable",503)]
    public async Task Exact_decisions_map_to_ephemeral_subject_or_redacted_refusal(string kind,int expected)
    {
        using var f=new ClientFixture();int calls=0;await using var app=f.ServerApp(async c=>{calls++;var reply=ClientFixture.Reply(await ClientFixture.Read(c));if(kind!="active"){reply.Decision=kind switch{"unauthenticated"=>Decision.Unauthenticated,"forbidden"=>Decision.Forbidden,_=>Decision.Unavailable};ClearSubject(reply);}await ClientFixture.Write(c,reply.ToByteArray());});await app.StartAsync(TestContext.Current.CancellationToken);await using var client=new SessionValidatorClient(f.Options());var result=await client.ValidateAsync("private-token-canary","backup.read",DateTimeOffset.UtcNow.AddSeconds(2),TestContext.Current.CancellationToken);Assert.Equal(expected,result.HttpStatusCode);Assert.Equal(1,calls);if(expected==200){Assert.NotNull(result.Subject);Assert.Equal(Guid.Parse("12345678-1234-4234-8234-123456789abc"),result.Subject.AccountId);Assert.Equal(7,result.Subject.Generation);}else Assert.Null(result.Subject);Assert.DoesNotContain("private-token",result.ToString());Assert.DoesNotContain("12345678",result.Subject?.ToString()??"");
    }
    internal static void ClearSubject(ValidateReply r){r.AccountIdUuid=ByteString.Empty;r.SessionFamilyUuid=ByteString.Empty;r.Generation=0;r.SessionProtocolVersion=0;r.ValidUntilUnixMs=0;}
    [Theory][InlineData("unknown-field")][InlineData("duplicate")][InlineData("wrong-wire")][InlineData("malformed")][InlineData("oversized")][InlineData("version")][InlineData("decision-zero")][InlineData("decision-unknown")][InlineData("request")][InlineData("policy")][InlineData("decision-id")][InlineData("checked-future")][InlineData("checked-old")][InlineData("expired")][InlineData("beyond-deadline")][InlineData("empty-account")][InlineData("zero-account")][InlineData("short-family")][InlineData("zero-family")][InlineData("generation-zero")][InlineData("generation-large")][InlineData("protocol")][InlineData("refusal-account")][InlineData("refusal-family")][InlineData("refusal-generation")][InlineData("refusal-protocol")][InlineData("refusal-validity")]
    public async Task Hostile_raw_reply_never_returns_identity(string fault)
    {
        using var f=new ClientFixture();int calls=0;await using var app=f.ServerApp(async c=>{calls++;var r=ClientFixture.Reply(await ClientFixture.Read(c));if(fault.StartsWith("refusal-",StringComparison.Ordinal)){r.Decision=Decision.Forbidden;ClearSubject(r);}switch(fault){
        case "version":r.ContractVersion=2;break;case "decision-zero":r.Decision=Decision.Unspecified;break;case "decision-unknown":r.Decision=(Decision)90;break;case "request":r.RequestId=Guid.NewGuid().ToString("N");break;case "policy":r.PolicyVersion="other.v1";break;case "decision-id":r.DecisionId="user-account";break;case "checked-future":r.CheckedAtUnixMs=DateTimeOffset.UtcNow.AddSeconds(5).ToUnixTimeMilliseconds();break;case "checked-old":r.CheckedAtUnixMs=1;break;case "expired":r.ValidUntilUnixMs=1;break;case "beyond-deadline":r.ValidUntilUnixMs=DateTimeOffset.UtcNow.AddSeconds(10).ToUnixTimeMilliseconds();break;case "empty-account":r.AccountIdUuid=ByteString.Empty;break;case "zero-account":r.AccountIdUuid=ByteString.CopyFrom(new byte[16]);break;case "short-family":r.SessionFamilyUuid=ByteString.CopyFrom(new byte[15]);break;case "zero-family":r.SessionFamilyUuid=ByteString.CopyFrom(new byte[16]);break;case "generation-zero":r.Generation=0;break;case "generation-large":r.Generation=9007199254740992;break;case "protocol":r.SessionProtocolVersion=1;break;case "refusal-account":r.AccountIdUuid=UuidCodec.Encode(Guid.NewGuid());break;case "refusal-family":r.SessionFamilyUuid=UuidCodec.Encode(Guid.NewGuid());break;case "refusal-generation":r.Generation=1;break;case "refusal-protocol":r.SessionProtocolVersion=2;break;case "refusal-validity":r.ValidUntilUnixMs=100;break;}
        byte[] b=r.ToByteArray();b=fault switch{"unknown-field"=>[..b,0x60,0x01],"duplicate"=>[..b,0x08,0x01],"wrong-wire"=>[0x0a,0x01,0x01],"malformed"=>[0x12,0xff],"oversized"=>new byte[1025],_=>b};await ClientFixture.Write(c,b);});await app.StartAsync(TestContext.Current.CancellationToken);await using var client=new SessionValidatorClient(f.Options());var result=await client.ValidateAsync("private-token","backup.read",DateTimeOffset.UtcNow.AddSeconds(2),TestContext.Current.CancellationToken);Assert.Equal(503,result.HttpStatusCode);Assert.Null(result.Subject);Assert.Equal(1,calls);
    }
    [Theory][InlineData("grpc-error")][InlineData("http-error")][InlineData("redirect")][InlineData("gzip")][InlineData("empty")][InlineData("no-store")][InlineData("extra-message")][InlineData("headers")]
    public async Task Transport_faults_are_503_with_no_application_retry(string fault)
    {
        using var f=new ClientFixture();int calls=0;await using var app=f.ServerApp(async c=>{calls++;var r=ClientFixture.Reply(await ClientFixture.Read(c));if(fault=="http-error"){c.Response.StatusCode=503;return;}if(fault=="redirect"){c.Response.StatusCode=302;c.Response.Headers.Location="https://localhost/other";return;}if(fault=="gzip")c.Response.Headers["grpc-encoding"]="gzip";if(fault=="headers")c.Response.Headers["padding"]=new string('x',5000);if(fault=="no-store"){c.Response.ContentType="application/grpc";c.Response.Headers["grpc-status"]="0";return;}
        if(fault=="extra-message"){var b=r.ToByteArray();c.Response.ContentType="application/grpc";c.Response.Headers.CacheControl="no-store";c.Response.DeclareTrailer("grpc-status");for(int i=0;i<2;i++){var frame=new byte[b.Length+5];System.Buffers.Binary.BinaryPrimitives.WriteInt32BigEndian(frame.AsSpan(1),b.Length);b.CopyTo(frame,5);await c.Response.Body.WriteAsync(frame);}c.Response.AppendTrailer("grpc-status","0");return;}await ClientFixture.Write(c,fault=="empty"?[]:r.ToByteArray(),fault=="grpc-error"?14:0);});await app.StartAsync(TestContext.Current.CancellationToken);await using var client=new SessionValidatorClient(f.Options());var result=await client.ValidateAsync("credential","backup.read",DateTimeOffset.UtcNow.AddSeconds(2),TestContext.Current.CancellationToken);Assert.Equal(503,result.HttpStatusCode);Assert.Null(result.Subject);Assert.Equal(1,calls);
    }
    [Theory][InlineData(false)][InlineData(true)]
    public async Task Maximum_utf8_credential_and_copied_rotation_pins_work_over_actual_tls(bool multiByte)
    {
        using var f=new ClientFixture();using var next=f.Leaf(true);string credential=multiByte?new string('ü',4096):new string('x',8192);await using var app=f.ServerApp(async c=>{var r=await ClientFixture.Read(c);Assert.Equal(8192,r.AccessCredential.Length);Assert.Equal(credential,r.AccessCredential.ToStringUtf8());await ClientFixture.Write(c,ClientFixture.Reply(r).ToByteArray());});await app.StartAsync(TestContext.Current.CancellationToken);var options=f.Options(j=>j["serverLeafSha256"]=new System.Text.Json.Nodes.JsonArray(ClientFixture.Pin(f.Server),ClientFixture.Pin(next)));await using var client=new SessionValidatorClient(options);options.ServerLeafSha256[0]=new string('0',64);Assert.Equal(200,(await client.ValidateAsync(credential,"backup.read",DateTimeOffset.UtcNow.AddSeconds(2),TestContext.Current.CancellationToken)).HttpStatusCode);
    }
}
